import {SCOPES,STATES,CONFIDENCE,PRIORITIES,MAX_BYTES,demoWorkspace,parseWorkspace,serializeWorkspace,searchAssessments,evidenceSummary,updateAssessment,addEvidence,addAssessment,exportAssessment} from './threat-core.mjs';
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const options=(values,current)=>values.map(v=>`<option${v===current?' selected':''}>${esc(v)}</option>`).join('');
const uid=prefix=>`${prefix}-${crypto.randomUUID()}`;
let workspace=demoWorkspace(),selected=workspace.assessments[0].id,view='desk',dirty=false,draft=false;
let saveSnapshot=null;
let filters={query:'',scope:'All',status:'All'};
function feedback(message,error=false){$('feedback').textContent=message;$('feedback').classList.toggle('error',error);}
function changed(){dirty=true;saveSnapshot=null;$('confirm-saved').hidden=true;$('save').textContent='Save workspace •';}
function leaveDraft(){if(!draft)return true;feedback('Apply the assessment draft before changing views or records.',true);return false;}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function drawStats(){
  $('stats').innerHTML=[['Assessments',workspace.assessments.length],['Awaiting review',workspace.assessments.filter(c=>c.status!=='Reviewed').length],['Evidence records',workspace.evidence.length],['Challenging records',workspace.evidence.filter(e=>e.relation==='Challenges').length]].map(([label,n])=>`<div><span>${label}</span><strong>${n}</strong></div>`).join('');
  $('notice').textContent=`${workspace.evidence.filter(e=>e.synthetic).length} synthetic training records; other records are analyst-entered and unverified by the application. No live feed or attack predictions. Save a workspace file to retain changes.`;
}
function drawList(){
  const rows=searchAssessments(workspace,filters);
  if(!rows.some(c=>c.id===selected))selected=rows[0]?.id||null;
  $('case-list').innerHTML=rows.length?rows.map(c=>`<button class="finding" data-case="${c.id}" aria-pressed="${c.id===selected}"><span class="small-label">${esc(c.scope)} / ${esc(c.area)}</span><span class="finding-main"><strong>${esc(c.title)}</strong></span><span class="finding-meta">As of ${c.asOf}</span><span class="tags"><span class="tag state">${c.status}</span><span class="tag">${c.confidence} confidence</span><span class="tag">${c.priority}</span></span></button>`).join(''):'<p class="empty">No assessments match these filters.</p>';
  $('result-count').textContent=`${rows.length} assessments in this view`;
}
function drawDetail(){
  const c=workspace.assessments.find(c=>c.id===selected);
  if(!c){$('case-detail').innerHTML='<p class="empty">Select an assessment or create a new intelligence question.</p>';return;}
  const s=evidenceSummary(workspace,c.id);
  $('case-detail').innerHTML=`<div class="panel-heading"><h2>Evidence & assessment</h2><button id="add-evidence">Add evidence</button></div><div class="case-body"><div class="case-heading"><div><p class="small-label">${c.scope} / ${esc(c.area)}</p><h2>${esc(c.title)}</h2></div><span class="chip">${c.status}</span></div><p>${esc(c.question)}</p><div class="notice">${s.records} records · ${s.sourceGroups} supporting source groups · ${s.challenging} challenging records. These are analyst-assigned labels, not proof of independent corroboration.</div><h3>Evidence timeline</h3>${s.timeline.map(e=>`<article class="evidence-record" data-relation="${e.relation}"><span class="small-label">${e.id} / ${e.reportedAt}${e.synthetic?' / SYNTHETIC':''}</span><h3>${esc(e.title)}</h3><div class="tags"><span class="tag">${e.claimState}</span><span class="tag">${e.relation}</span></div><p>${esc(e.statement)}</p><p class="muted">Publisher: ${esc(e.publisher)} · Source group: ${esc(e.originGroup)} · Recorded: ${e.recordedAt}</p>${e.url?`<a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">Open source reference (unverified by app)</a>`:'<p class="muted">Synthetic training record; no real publisher claim.</p>'}</article>`).join('')||'<p class="muted">No evidence recorded. Assessments must cite evidence before review.</p>'}<form id="assessment-form"><h3>Analyst judgment</h3><div class="assessment-fields"><div><label for="review-confidence">Confidence (analyst assigned)</label><select id="review-confidence">${options(CONFIDENCE,c.confidence)}</select></div><div><label for="review-priority">Review priority</label><select id="review-priority">${options(PRIORITIES,c.priority)}</select></div><div><label for="review-state">Review status</label><select id="review-state">${options(STATES,c.status)}</select></div></div><label for="review-asof">Assessment as-of date</label><input id="review-asof" type="date" value="${c.asOf}" required><label for="review-judgment">Judgment and reasoning</label><textarea id="review-judgment" maxlength="4000" rows="4">${esc(c.judgment)}</textarea><label for="review-gaps">Information gaps and alternative explanations</label><textarea id="review-gaps" maxlength="2000" rows="3">${esc(c.gaps)}</textarea><fieldset><legend>Cited evidence</legend>${s.timeline.map(e=>`<label class="checkline"><input type="checkbox" name="citation" value="${e.id}"${c.citedEvidence.includes(e.id)?' checked':''}><span>${e.id} — ${esc(e.title)}</span></label>`).join('')||'<p class="muted">Add evidence to enable citations.</p>'}</fieldset><label for="review-note">Review note</label><textarea id="review-note" maxlength="2000" rows="2">${esc(c.reviewNote)}</textarea>${s.challenging?'<label class="checkline"><input id="ack-challenges" type="checkbox"><span>I considered the challenging evidence and documented its implications in the review note.</span></label>':''}<p class="muted">Reviewed is a workflow label, not agency approval. Confidence is not an attack probability. Relevant evidence, gaps, citations and a review note are required.</p><p id="review-error" class="error" role="alert"></p><p id="draft-indicator" class="draft-banner"></p><div class="actions"><button class="primary" type="submit">Apply assessment</button><button id="export-brief" type="button">Export assessment brief</button></div></form></div>`;
}
function drawDesk(){
  $('content').innerHTML=`<div class="case-layout"><section class="panel"><div class="panel-heading"><h2>Assessment queue</h2></div><div class="filters"><label class="sr-only" for="case-search">Search assessments</label><input id="case-search" type="search" placeholder="Search title, area, question…" value="${esc(filters.query)}"><label class="sr-only" for="scope-filter">Scope filter</label><select id="scope-filter">${options(['All',...SCOPES],filters.scope)}</select><label class="sr-only" for="state-filter">Review status filter</label><select id="state-filter">${options(['All',...STATES],filters.status)}</select></div><div id="case-list" class="case-list"></div><p id="result-count" class="page-copy muted"></p></section><section id="case-detail" class="panel" aria-label="Selected assessment"></section></div>`;
  drawList();drawDetail();
}
function drawMethod(){
  $('content').innerHTML=`<section class="panel"><div class="panel-heading"><h2>Sources, method & intended use</h2></div><div class="page-copy"><h3>Terrorism intelligence research workflow</h3><p>Organize public reports and authorized customer evidence around an intelligence question. Separate reported statements from analyst inference, retain contradictions, document gaps, and cite the evidence used in a judgment. This prototype does not collect live intelligence or forecast attacks.</p><div class="reference-grid"><div><h3>India primary references</h3><a href="https://nia.gov.in/press-releases" target="_blank" rel="noopener noreferrer">NIA public releases</a><a href="https://www.mha.gov.in/en/divisionofmha/counter-terrorism-and-counter-radicalization-division" target="_blank" rel="noopener noreferrer">MHA counter-terrorism division</a><p>Reference links only. No NIA/MHA reports are bundled or automatically ingested. A publisher's allegation must remain attributed and distinct from an adjudicated fact.</p></div><div><h3>International context</h3><a href="https://www.un.org/counterterrorism/en/un-global-counter-terrorism-strategy" target="_blank" rel="noopener noreferrer">UN counter-terrorism strategy</a><p>International reports require source, date and relevance review. Similar timing or nearby geography does not establish shared perpetrators, intent or causation.</p></div></div><h3>Corroboration and uncertainty</h3><p>Reposts can share an underlying source group. Multiple reports are not automatically independent. Confidence, priority, relationships and claim states are assigned by the analyst. New evidence reopens Reviewed assessments. The app does not independently verify that a review note adequately addresses contradictions.</p><h3>Data handling</h3><p>No analytics, customer-data uploads, AI calls, browser storage or automatic saves are included. Workspace save/open uses JSON with a 2 MB UTF-8 limit. Files and review history are editable and unencrypted. Imported provenance is not trusted. Evaluate with synthetic or approved non-sensitive data.</p><h3>Government product path</h3><p>The intended business is licensed agency software with customer-controlled deployment and support. Production access control, protected audit trails, approvals, retention, lawful data connectors and independent security evaluation must be scoped with a pilot customer. This preview is not an operational or accredited agency system.</p><h3>Cyber module</h3><p><a href="./exposure.html">Cyber exposure analysis</a> remains available as a supporting defensive workflow. Authorized security testing requires defined scope and permission.</p></div></section>`;
}
function render(){drawStats();document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='desk')drawDesk();else if(view==='method')drawMethod();else $('content').innerHTML=`<section class="panel"><div class="panel-heading"><h2>Review history</h2><span class="muted">${workspace.history.length} changes</span></div><p class="page-copy muted">Editable local history, not a protected audit trail.</p>${[...workspace.history].reverse().slice(0,100).map(h=>`<article class="history-item"><span class="small-label">${h.at}</span><h3>${esc(h.action)}</h3><p>${esc(h.assessmentId)} · ${esc(h.note)}</p></article>`).join('')||'<p class="empty">No changes recorded yet.</p>'}</section>`;}
document.addEventListener('click',event=>{
  const b=event.target.closest('button');if(!b)return;
  if(b.dataset.close){$(b.dataset.close).close();return;}
  if(b.dataset.view){if(!leaveDraft())return;view=b.dataset.view;render();return;}
  if(b.dataset.case){if(!leaveDraft())return;selected=b.dataset.case;drawList();drawDetail();return;}
  try{switch(b.id){
    case 'save':if(!leaveDraft())return;saveSnapshot=serializeWorkspace(workspace);download('ruthless-threat-workspace.json',saveSnapshot,'application/json');$('confirm-saved').hidden=false;feedback('Download requested. Confirm that your browser saved the JSON file before marking this workspace saved.');break;
    case 'confirm-saved':if(!leaveDraft())return;if(saveSnapshot!==serializeWorkspace(workspace))throw new Error('Workspace changed since download. Save it again.');dirty=false;$('save').textContent='Save workspace';b.hidden=true;feedback('File receipt acknowledged. Keep that JSON file to reopen this workspace.');break;
    case 'open':if(leaveDraft())$('workspace-file').click();break;
    case 'new-case':if(!leaveDraft())return;$('case-error').textContent='';$('case-form').reset();$('case-date').value=today();$('case-dialog').showModal();break;
    case 'add-evidence':if(!leaveDraft())return;$('ev-error').textContent='';$('evidence-form').reset();$('ev-date').value=today();$('ev-recorded').value=today();$('evidence-dialog').dataset.caseId=selected;$('evidence-dialog').showModal();break;
    case 'export-brief':if(!leaveDraft())return;download('ruthless-threat-assessment.md',exportAssessment(workspace,selected),'text/markdown');feedback('Brief download requested. Confirm that your browser saved the Markdown file.');break;
  }}catch(e){feedback(e.message,true);}
});
document.addEventListener('input',event=>{
  if(event.target.closest('#assessment-form')){draft=true;$('draft-indicator').textContent='Unapplied assessment changes';}
  if(event.target.id==='case-search'){if(!leaveDraft()){event.target.value=filters.query;return;}filters.query=event.target.value;drawList();drawDetail();}
});
document.addEventListener('change',async event=>{
  const e=event.target;
  if(['scope-filter','state-filter'].includes(e.id)){const key=e.id==='scope-filter'?'scope':'status';if(!leaveDraft()){e.value=filters[key];return;}filters[key]=e.value;drawList();drawDetail();}
  if(e.closest('#assessment-form')){draft=true;$('draft-indicator').textContent='Unapplied assessment changes';}
  if(e.id==='workspace-file')try{const file=e.files[0];if(!file)return;if(file.size>MAX_BYTES)throw new Error('File exceeds 2 MB.');const original=workspace;const next=parseWorkspace(await file.text());if(workspace!==original||draft)throw new Error('Workspace changed while opening. Retry after saving current work.');if(dirty&&!confirm('Replace current workspace? Save a file first to retain changes.'))return;workspace=next;selected=next.assessments[0].id;filters={query:'',scope:'All',status:'All'};view='desk';dirty=false;saveSnapshot=null;$('confirm-saved').hidden=true;$('save').textContent='Save workspace';render();feedback('Workspace restored. Sources, confidence and history are unverified external file content.');}catch(err){feedback(err.message,true);}finally{e.value='';}
});
document.addEventListener('submit',event=>{
  const form=event.target;if(!['case-form','evidence-form','assessment-form'].includes(form.id))return;event.preventDefault();
  try{
    if(form.id==='case-form'){
      const record={id:uid('case'),title:$('case-title').value,area:$('case-area').value,scope:$('case-scope').value,asOf:$('case-date').value,question:$('case-question').value,judgment:'',gaps:'',confidence:'Insufficient',priority:'Routine',status:'Draft',reviewNote:'',citedEvidence:[]};workspace=addAssessment(workspace,record,today());selected=record.id;filters={query:'',scope:'All',status:'All'};view='desk';$('case-dialog').close();
    }else if(form.id==='evidence-form'){
      workspace=addEvidence(workspace,{id:uid('ev'),assessmentId:$('evidence-dialog').dataset.caseId,title:$('ev-title').value,publisher:$('ev-publisher').value,originGroup:$('ev-origin').value,url:$('ev-url').value,reportedAt:$('ev-date').value,recordedAt:$('ev-recorded').value,statement:$('ev-statement').value,claimState:$('ev-state').value,relation:$('ev-relation').value,synthetic:$('ev-synthetic').checked},today());$('evidence-dialog').close();
    }else{
      workspace=updateAssessment(workspace,selected,{confidence:$('review-confidence').value,priority:$('review-priority').value,status:$('review-state').value,asOf:$('review-asof').value,judgment:$('review-judgment').value,gaps:$('review-gaps').value,reviewNote:$('review-note').value,citedEvidence:[...form.querySelectorAll('input[name="citation"]:checked')].map(e=>e.value),challengesAcknowledged:$('ack-challenges')?.checked||false},today());draft=false;
    }
    changed();render();feedback('Change applied to this session. Save workspace to retain it.');
  }catch(e){$(form.id==='case-form'?'case-error':form.id==='evidence-form'?'ev-error':'review-error').textContent=e.message;}
});
window.addEventListener('beforeunload',e=>{if(dirty||draft){e.preventDefault();e.returnValue='';}});
render();
